import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebasNeue = makeLoadFont('BebasNeue');

const { fontFamily: bebasNeueFamily } = loadBebasNeue();



export type LowerThirdProps = Record<string, any>;

const LowerThird: React.FC<LowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 6,
  chipColor = "#000000",
  textColor = "#FFFFFF",
  iconColor = "#FFFFFF",
  text = "ARRIVE 30 MIN EARLY",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const totalFrames = durationInSeconds * fps;
  const slideInFrames = Math.round(0.4 * fps);
  const slideOutFrames = Math.round(0.3 * fps);
  const slideOutStart = totalFrames - slideOutFrames;

  // Sweep animation happens slightly longer than the slide-in for smooth overlap
  const sweepDuration = Math.round(0.8 * fps);

  // Position calculation
  const paddingX = width * 0.08;
  const offScreenX = -(width * 0.4); // Ensures it completely leaves the left edge

  const slideIn = interpolate(frame, [0, slideInFrames], [offScreenX, paddingX], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  const slideOut = interpolate(
    frame,
    [slideOutStart, totalFrames],
    [paddingX, offScreenX],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.ease),
    }
  );

  const currentX = frame >= slideOutStart ? slideOut : slideIn;

  // Clock hands sweep
  const minuteSweep = interpolate(frame, [0, sweepDuration], [0, 360], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  const hourSweep = interpolate(frame, [0, sweepDuration], [0, 30], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          left: currentX,
          bottom: height * 0.08, // 8% padding from bottom edge
          height: 80,
          borderRadius: 40,
          backgroundColor: chipColor,
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          padding: "0 32px",
          gap: "16px",
          transition: "none",
        }}
      >
        <svg
          width="40"
          height="40"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{ transition: "none", flexShrink: 0 }}
        >
          <circle cx="12" cy="12" r="10" stroke={iconColor} strokeWidth="1.5" />
          <g transform={`rotate(${hourSweep} 12 12)`}>
            <line
              x1="12"
              y1="12"
              x2="12"
              y2="7.5"
              stroke={iconColor}
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </g>
          <g transform={`rotate(${minuteSweep} 12 12)`}>
            <line
              x1="12"
              y1="12"
              x2="12"
              y2="4"
              stroke={iconColor}
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </g>
        </svg>

        <span
          style={{
            fontFamily: bebasNeueFamily,
            fontWeight: "bold",
            fontSize: "40px",
            color: textColor,
            lineHeight: 1,
            letterSpacing: "0.05em",
            whiteSpace: "nowrap",
            transition: "none",
            marginTop: "4px", // Minor optical baseline adjustment for Bebas Neue
          }}
        >
          {text}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default LowerThird;